INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_iscac_1', 'oa_iscac_customs', 'large-appliance delivery acceptance and rescheduling rules', 'reschedule a home visit for severe weather or unsuitable site conditions；service records retain the original case number and appointment history。', 'https://service.example/delivery-installation', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_iscac_2', 'oa_iscac_brand', 'official warranty, credentials, and overseas after-sales notes', 'official installation records include the compatible model, installer credentials, home-visit code, and published fees；installation acceptance records support later after-sales claims。', 'https://brand.example/notice', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_iscac_3', 'oa_iscac_card', 'overseas and foreign-currency card safety tips', 'foreign-currency postings may have exchange-rate and timing differences；check promptly and open a dispute for duplicate charges or unfamiliar merchants。', 'https://card.example/fx-safety', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_iscac_4', 'oa_iscac_brand', 'comparison of three handling options', 'official rework requires an additional payment ¥780；rescheduling licensed third-party installation is expected to require an additional payment ¥450；self-remediation can be submitted for reimbursement，materials are estimated at ¥600 and valid receipts are required。', 'https://brand.example/options', '2026-06-08');
